            "minLength": 22,
            "type": "string"
        },
        "sg_message_id": {
            "description": "A unique, internal SendGrid ID for the message. The first half of this is pulled from the smtp-id.",
            "type": "string"
        },
        "smtp-id": {
            "description": "A unique ID attached to the message by the originating system",
            "type": "string"
